# -*- coding: utf-8 -*-
"""프로젝트 30개의 장치 도해 조각 — 사이펀
   배치 규칙 : 윗줄 부품 ①②③ 은 y 56~150 · x 가 왼쪽/가운데/오른쪽 1/3 에, 아랫줄 ④⑤⑥ 은 y 156~198 · 같은 1/3 에 둔다.
   (라벨 ①②③ 은 위, ④⑤⑥ 은 아래 고정 칸이라 지시선이 짧아진다) + 지시선 목표점(tg). 라벨 ①~⑥ 은 JS(svgFig)가 고정 칸에 그린다.
   색 규약 : 장치 #475569/#94a3b8 · 빔·파동 #7dd3fc/#fbbf24 · 정답 #34d399 · 경고 #fb7185 · 치수 #a78bfa"""
import math
PF={}
def T(x,y,s,c='#cfe0f5',sz=11,anc=None,w=None):
    return '<text x="%g" y="%g" fill="%s" font-size="%g"%s%s>%s</text>'%(x,y,c,sz,(' text-anchor="%s"'%anc if anc else ''),(' font-weight="%s"'%w if w else ''),s)
def R(x,y,w,h,rx=4,f='#475569',s='#94a3b8',sw=1.3):
    return '<rect x="%g" y="%g" width="%g" height="%g" rx="%g" fill="%s" stroke="%s" stroke-width="%g"/>'%(x,y,w,h,rx,f,s,sw)
def C(cx,cy,r,f='none',s='#94a3b8',sw=1.3):
    return '<circle cx="%g" cy="%g" r="%g" fill="%s" stroke="%s" stroke-width="%g"/>'%(cx,cy,r,f,s,sw)
def E(cx,cy,rx,ry,f='none',s='#94a3b8',sw=1.3):
    return '<ellipse cx="%g" cy="%g" rx="%g" ry="%g" fill="%s" stroke="%s" stroke-width="%g"/>'%(cx,cy,rx,ry,f,s,sw)
def L(x1,y1,x2,y2,c='#94a3b8',w=1.2,dash=None):
    return '<path d="M%g %g L%g %g" stroke="%s" stroke-width="%g"%s/>'%(x1,y1,x2,y2,c,w,(' stroke-dasharray="%s"'%dash if dash else ''))
def P(d,c='#94a3b8',w=1.3,f='none',dash=None):
    return '<path d="%s" stroke="%s" stroke-width="%g" fill="%s"%s/>'%(d,c,w,f,(' stroke-dasharray="%s"'%dash if dash else ''))
def AR(x1,y1,x2,y2,c='#fbbf24',w=2):
    dx,dy=x2-x1,y2-y1; n=math.hypot(dx,dy) or 1; ux,uy=dx/n,dy/n
    return L(x1,y1,x2,y2,c,w)+'<path d="M%g %g L%g %g L%g %g Z" fill="%s"/>'%(x2,y2,x2-ux*9-uy*4.5,y2-uy*9+ux*4.5,x2-ux*9+uy*4.5,y2-uy*9-ux*4.5,c)
def reg(i,parts,tg): PF[i]=(''.join(parts),tg)

# ── 공용 아이콘(유체) ──
def WTR(x,y,w,h,a=.28): return R(x,y,w,h,0,'rgba(56,189,248,%g)'%a,'none',0)
def TANK(x,y,w,h,lv=0.7,col='#94a3b8'):
    return WTR(x+1,y+h*(1-lv),w-2,h*lv)+P('M%g %g V%g H%g V%g'%(x,y,y+h,x+w,y),col,2)+L(x,y+h*(1-lv),x+w,y+h*(1-lv),'#7dd3fc',1.2)
def SYR(x,y,l=70,h=16,pl=0.5,col='#94a3b8'):
    return R(x,y,l,h,2,'rgba(56,189,248,.25)',col,1.5)+R(x+l*pl-3,y+2,6,h-4,1,'#e2e8f0','#e2e8f0',1)+L(x+l*pl,y+h/2,x-14+0*pl,y+h/2,'#e2e8f0',2)+R(x+l+0,y+h/2-2,12,4,1,'#94a3b8','none',0)
def BLK(x,y,w,h,col='#94a3b8'): return R(x,y,w,h,3,col,'#e2e8f0',1.2)
def SCALEB(x,y,s='g'): return R(x,y,64,34,4,'#1e293b','#94a3b8',1.4)+R(x+8,y+6,48,12,2,'#0b1424','#34d399',1)+T(x+32,y+16,s,'#34d399',10,'middle')
def SPRINGS(x,y,h=46):
    pts=' '.join('%g,%g'%(x+(5 if i%2 else -5),y+6+i*(h-12)/8) for i in range(9))
    return L(x,y-8,x,y+6,'#94a3b8',1.4)+'<polyline points="%s" fill="none" stroke="#94a3b8" stroke-width="1.6"/>'%pts+R(x-7,y+h-6,14,6,1,'#fbbf24','none',0)
def BOATB(x,y,w=70,h=22): return P('M%g %g L%g %g L%g %g L%g %g Z'%(x,y,x+8,y+h,x+w-8,y+h,x+w,y),'#94a3b8',1.6,'rgba(148,163,184,.5)')
def JETP(x0,y0,x1,y1,col='#7dd3fc'): return P('M%g %g Q%g %g %g %g'%(x0,y0,(x0+x1)/2+8,y0-6,x1,y1),col,2)
def GAUGE(cx,cy,r=16,v=0.6):
    a=-2.4+3.4*v
    return C(cx,cy,r,'#0b1424','#94a3b8',1.5)+L(cx,cy,cx+r*0.78*math.cos(a),cy+r*0.78*math.sin(a),'#fb7185',2)
def UTUBE(x,y,w=40,h=50): return P('M%g %g V%g Q%g %g %g %g'%(x,y,y+h-12,x,y+h,x+12,y+h),'#94a3b8',2)+L(x+12,y+h,x+w-12,y+h,'#94a3b8',2)+P('M%g %g Q%g %g %g %g V%g'%(x+w-12,y+h,x+w,y+h,x+w,y+h-12,y),'#94a3b8',2)
def HOSE(x1,y1,x2,y2): return P('M%g %g C%g %g %g %g %g %g'%(x1,y1,x1+30,y1+30,x2-30,y2-30,x2,y2),'#7dd3fc',3)
def BOX(x,y,w,h,s,c='#fbbf24'): return R(x,y,w,h,6,'#0b1424','#3d5480',1.2)+T(x+w/2,y+h/2+4,s,c,11,'middle','700')
def PHONE(x,y,lab=''): return R(x,y,26,46,5,'#1e293b','#94a3b8')+C(x+13,y+8,3,'#0f172a','#34d399',1)+(T(x+13,y+34,lab,'#34d399',9,'middle') if lab else '')
def ARD(x,y): return R(x,y,56,34,3,'#0f3d2e','#34d399',1.3)+R(x+18,y+10,18,14,2,'#0b1424','#94a3b8',1)
def PLOT(x,y,w,h,pts=None,col='#38bdf8'):
    o=[L(x,y+h,x+w,y+h,'#5b7099',1.2),L(x,y,x,y+h,'#5b7099',1.2)]
    if pts: o.append(P('M'+' L'.join('%g %g'%(x+px*w,y+h-py*h) for px,py in pts),col,1.8))
    return ''.join(o)
def BARS(x,y,w,h,vals,cols):
    n=len(vals); bw=w/n-4
    return ''.join(R(x+i*(bw+4),y+h-v*h,bw,v*h,1,cols[i%len(cols)],'none',0) for i,v in enumerate(vals))+L(x,y+h,x+w,y+h,'#5b7099',1.2)
def LAB(x,y,s,c='#9db0cc',sz=10.5,anc='start'): return T(x,y,s,c,sz,anc)
def WARN(cx,cy,s=1.0): return P('M%g %g L%g %g L%g %g Z'%(cx,cy-12*s,cx-12*s,cy+10*s,cx+12*s,cy+10*s),'#fb7185',1.6,'rgba(251,113,133,.15)')+T(cx,cy+6*s,'!','#fb7185',13*s,'middle','700')
BT=[(115,177),(335,177),(585,177)]
def fig(i,top,bot,tg3):
    """top : 3 개 조각(문자열) · bot : 3 개 (문자열, 색) · tg3 : 윗줄 지시선 목표 3 점"""
    b=[BOX(30,160,170,34,bot[0][0],bot[0][1]),BOX(260,160,150,34,bot[1][0],bot[1][1]),BOX(500,160,170,34,bot[2][0],bot[2][1])]
    reg(i,list(top)+b,list(tg3)+BT)

# ── 베르누이 전용 부품 ──
def FANP(x,y,r=18): return C(x,y,r,'rgba(148,163,184,.12)','#94a3b8',2)+L(x,y-r*0.8,x,y+r*0.8,'#e2e8f0',2)+L(x-r*0.7,y+r*0.45,x+r*0.7,y-r*0.45,'#e2e8f0',2)+R(x-4,y+r,8,14,1,'#475569','none',0)
def WINDA(x,y,n=3,l=30,dy=14): return ''.join(AR(x,y+k*dy,x+l,y+k*dy,'#7dd3fc',1.6) for k in range(n))
def PITOTP(x,y): return P('M%g %g H%g V%g'%(x,y,x+60,y+30),'#94a3b8',3)+C(x,y,3,'#fbbf24','none',0)+L(x+30,y-3,x+30,y-9,'#94a3b8',2)
def WINGP(x,y,w=70,ang=0): return '<g transform="rotate(%g %g %g)">%s</g>'%(-ang,x,y,P('M%g %g C%g %g %g %g %g %g C%g %g %g %g %g %g Z'%(x-w/2,y,x-w/2+6,y-12,x+w*0.1,y-14,x+w/2,y+1,x+w*0.1,y+4,x-w/2+8,y+6,x-w/2,y),'#e2e8f0',1.6,'rgba(148,163,184,.55)'))
def VPIPE(x,y,w=150,h1=36,h2=16):
    return P('M%g %g H%g L%g %g H%g L%g %g H%g'%(x,y-h1/2,x+w*0.3,x+w*0.45,y-h2/2,x+w*0.55,x+w*0.7,y-h1/2,x+w),'#94a3b8',2.2)+P('M%g %g H%g L%g %g H%g L%g %g H%g'%(x,y+h1/2,x+w*0.3,x+w*0.45,y+h2/2,x+w*0.55,x+w*0.7,y+h1/2,x+w),'#94a3b8',2.2)
def BALL(x,y,r=12): return C(x,y,r,'#f8fafc','#94a3b8',1.5)+P('M%g %g Q%g %g %g %g'%(x-r*0.7,y-r*0.3,x,y-r*0.9,x+r*0.7,y-r*0.3),'#fb7185',1.2)
def BOTT(x,y,w=34,h=56,lv=0.7): return WTR(x+1,y+h*(1-lv),w-2,h*lv)+P('M%g %g V%g H%g V%g'%(x,y,y+h,x+w,y),'#94a3b8',2)
def STRAW(x,y,h=34): return R(x,y,5,h,1,'#e2e8f0','#94a3b8',1)
def LED(x,y,c='#34d399'): return C(x,y,6,c,'#e2e8f0',1)
def SERVO(x,y): return R(x,y,32,20,3,'#1e293b','#94a3b8',1.3)+R(x+32,y+6,8,8,1,'#94a3b8','none',0)
def TURB(x,y,l=26): return L(x,y,x,y+60,'#94a3b8',3)+''.join(L(x,y,x+l*math.cos(a),y+l*math.sin(a),'#e2e8f0',3) for a in (-1.5,0.6,2.7))+C(x,y,4,'#94a3b8','none',0)
def HOUSE(x,y,w=70,h=44): return R(x,y,w,h,2,'rgba(148,163,184,.12)','#94a3b8',1.6)+P('M%g %g L%g %g L%g %g'%(x-4,y,x+w/2,y-16,x+w+4,y),'#94a3b8',1.6)
def KITE(x,y,s=24): return P('M%g %g L%g %g L%g %g L%g %g Z'%(x,y-s,x+s*0.7,y,x,y+s*1.1,x-s*0.7,y),'#fbbf24',1.5,'rgba(251,191,36,.3)')+P('M%g %g q-8 14 4 24 t-4 24'%(x,y+s*1.1),'#94a3b8',1.2)
def SOCK(x,y): return L(x,y,x,y+54,'#94a3b8',3)+P('M%g %g L%g %g L%g %g L%g %g Z'%(x,y,x+54,y+4,x+54,y+12,x,y+16),'#fb923c',1.4,'rgba(251,146,60,.5)')
def PPAPER(x,y): return P('M%g %g L%g %g L%g %g Z'%(x,y,x+54,y+10,x,y+20),'#e2e8f0',1.5,'rgba(226,232,240,.4)')+L(x,y+10,x+40,y+10,'#94a3b8',1)
def CUP(x,y): return P('M%g %g L%g %g L%g %g L%g %g Z'%(x,y,x+8,y+28,x+34,y+28,x+42,y),'#94a3b8',1.8,'rgba(56,189,248,.3)')
def NOZ(x,y): return R(x,y,28,26,3,'#475569','#94a3b8',1.3)+''.join(L(x+28,y+5+k*6,x+54,y+3+k*7,'#7dd3fc',1.4) for k in range(3))
def DISC(x,y): return R(x,y,70,7,2,'#94a3b8','#e2e8f0',1.2)+C(x+35,y-12,11,'rgba(251,113,133,.5)','#fb7185',1.3)+R(x+31,y-2,8,4,1,'#475569','none',0)

# 공통 하단 박스 규약: 입력 → 변환 → 출력


# ── 사이펀 전용 부품 ──
WATER=WTR
def TNKO(x,y,w,h,col='#94a3b8'): return P('M%g %g V%g H%g V%g'%(x,y,y+h,x+w,y),col,2)
def SIP(x,y,flow=True,bub=False,w=150):
    """작은 사이펀 : (x,y) 왼쪽 위 · 폭 w · 높이 약 90"""
    s=w/150.0
    o=[WATER(x+2*s,y+30*s,48*s,50*s,.32)+TNKO(x,y+22*s,52*s,58*s)+L(x+2*s,y+30*s,x+50*s,y+30*s,'#7dd3fc',1.4)]
    d='M%g %g V%g Q%g %g %g %g H%g Q%g %g %g %g V%g'%(x+36*s,y+62*s,y+12*s,x+36*s,y+2*s,x+46*s,y+2*s,x+84*s,x+94*s,y+2*s,x+94*s,y+12*s,y+86*s)
    o.append(P(d,'#cbd5e1',6)+P(d,'#0b1424',3.4)+P(d,'#38bdf8' if flow else '#475569',2.4))
    if bub: o.append(R(x+62*s,y-2*s,8*s,8*s,2,'#e2e8f0','none',0))
    o.append(R(x+80*s,y+78*s,60*s,16*s,3,'rgba(56,189,248,.2)','#94a3b8',1.2))
    return ''.join(o)
def CYLN(x,y,h=60,lv=0.6): return R(x,y,16,h,2,'rgba(148,163,184,.1)','#94a3b8',1.4)+R(x+1,y+h*(1-lv),14,h*lv,0,'rgba(56,189,248,.4)','none',0)
def BKT(x,y,w=44,h=30): return P('M%g %g L%g %g L%g %g L%g %g'%(x,y,x+6,y+h,x+w-6,y+h,x+w,y),'#94a3b8',1.8,'rgba(148,163,184,.12)')
def WATCH(x,y): return C(x,y,13,'#0b1424','#e2e8f0',1.6)+L(x,y,x+6,y-6,'#fbbf24',1.8)+L(x,y,x,y-9,'#fb7185',1.2)+R(x-3,y-18,6,4,1,'#94a3b8','none',0)
def TNKW(x,y,w=50,h=60,lv=0.6): return TANK(x,y,w,h,lv)
def PLT(x,y,w=96,h=60,kind='sqrt'):
    if kind=='sqrt': pts=[(0,0),(.1,.35),(.3,.6),(.6,.82),(1,1)]
    elif kind=='lin': pts=[(0,0),(1,1)]
    elif kind=='dec': pts=[(0,1),(.3,.5),(.6,.3),(1,.18)]
    elif kind=='exp': pts=[(0,1),(.25,.55),(.5,.32),(1,.1)]
    elif kind=='step': pts=[(0,0.2),(.5,.2),(.5,1),(1,1)]
    elif kind=='saw': pts=[(0,0),(.4,1),(.5,0),(.9,1),(1,0)]
    else: pts=[(0,0.1),(.5,.5),(1,.95)]
    return PLOT(x,y,w,h,pts,'#34d399')
def HOSEC(x1,y1,x2,y2): return P('M%g %g C%g %g %g %g %g %g'%(x1,y1,x1+30,y1-40,x2-30,y2-40,x2,y2),'#7dd3fc',3)

# ═══ 30 개 도해 ═══
fig('R01',[SIP(30,66)+L(26,70,26,150,'#a78bfa',1,'3 3')+LAB(18,112,'h','#a78bfa',12), PLT(300,70,110,70,'sqrt')+LAB(300,64,'Q','#9db0cc',10)+LAB(400,152,'√h','#9db0cc',10), CYLN(570,76,70,0.5)+WATCH(620,100)],[('높이차 h 바꾸기','#fbbf24'),('Q ∝ √h','#7dd3fc'),('500 mL 받는 시간','#34d399')],[(60,100),(350,100),(590,108)])
fig('R02',[''.join(L(40,70+k*18,40+14*(k+1),70+k*18,'#cbd5e1',2+k*1.6) for k in range(4)), PLT(300,70,110,70,'sqrt')+LAB(300,64,'log Q','#9db0cc',10)+LAB(390,152,'log D','#9db0cc',10), LAB(570,96,'층류 D⁴','#38bdf8',12)+LAB(570,120,'난류 D²·⁵','#fb923c',12)],[('지름 3~16 mm','#fbbf24'),('로그–로그 기울기','#7dd3fc'),('지수 p 비교','#34d399')],[(80,100),(350,100),(600,108)])
fig('R03',[HOSEC(30,110,220,110)+LAB(110,140,'L','#a78bfa',12), PLT(300,70,110,70,'dec')+LAB(300,64,'Q','#9db0cc',10)+LAB(400,152,'L','#9db0cc',10), PLT(560,70,110,70,'lin')+LAB(560,64,'1/Q²','#9db0cc',10)],[('호스 길이 L','#fbbf24'),('길수록 유량 ↓','#7dd3fc'),('1/Q² 대 L 직선','#34d399')],[(125,110),(350,100),(610,100)])
fig('R04',[TNKW(50,66,70,80,0.8)+HOSEC(120,110,200,140), PLT(300,70,110,70,'exp')+LAB(300,64,'수위','#9db0cc',10)+LAB(400,152,'t','#9db0cc',10), WATCH(580,100)+PHONE(620,84,'영상')],[('통 단면적 A_t','#fbbf24'),('수위 h(t) 포물선','#7dd3fc'),('T = (A/a)√(2Kh₀/g)','#34d399')],[(85,106),(350,100),(595,104)])
fig('R05',[SIP(30,66,True,True)+LAB(110,56,'공기 방울','#e2e8f0',10), SYR(270,100,70,16,0.5)+HOSEC(340,108,470,128), PLT(570,70,100,70,'lin')+LAB(570,64,'h_min','#9db0cc',10)+LAB(660,152,'ℓ','#9db0cc',10)],[('기포 길이 ℓ','#fbbf24'),('주사기로 기포 만들기','#7dd3fc'),('h_min = ℓ + h_c','#34d399')],[(100,60),(310,108),(620,100)])
fig('R06',[SIP(30,66)+R(100,52,8,40,1,'rgba(56,189,248,.5)','#94a3b8',1)+LAB(112,56,'Δh','#fbbf24',11), PLT(300,70,110,70,'lin')+LAB(300,64,'Δh','#9db0cc',10)+LAB(400,152,'H_c','#9db0cc',10), GAUGE(600,104,22,0.35)+LAB(580,150,'p_c ↓','#fb7185',11)],[('정점 마노미터','#fbbf24'),('Δh = H_c + v²/2g','#7dd3fc'),('정점 압력 감소','#34d399')],[(104,70),(350,100),(600,104)])
